mapper.sql:
m.is_delete = 0
AND (
    m.user_id = #{currentUserId}
    OR (
        (m.user_id IS NULL OR m.user_id = 0)
        AND (
            m.org_id IS NULL
            OR m.org_id = 0

                OR m.org_id = #{currentOrgId}

        )
    )
)

mapper.select:
SELECT FROM sys_message_info_t m
AND m.msg_type = #{query.msgType}
AND m.sub_type = #{query.subType}
AND m.priority = #{query.priority}
AND m.read_status = #{query.readStatus}
AND m.read_status = 0
AND ( m.title LIKE CONCAT('%', #{query.keyword}, '%') OR m.content LIKE CONCAT('%', #{query.keyword}, '%') )
ORDER BY m.read_status ASC, CASE m.priority WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END ASC, m.create_time DESC, m.id DESC

mapper.update:
UPDATE sys_message_info_t m
SET m.read_status = 1,
    m.read_time = #{readTime},
    m.update_time = #{readTime}


    AND m.read_status = 0

        AND m.msg_type = #{msgType}
